function toast({title:s="",message:t="",type:o="info",duration:e=3e3,container:n="toast-header"}){const a=document.querySelector(n);if(a){const n=document.createElement("div");const i=setTimeout((function(){a.removeChild(n)}),e+1e3);n.onclick=function(s){if(s.target.closest(".toast__close")){a.removeChild(n);clearTimeout(i)}};const r={success:"fa-solid fa-circle-check",info:"fa-solid fa-circle-info",warning:"fa-solid fa-triangle-exclamation",error:"fa-solid fa-xmark"};const c=r[o];n.classList.add("toastt",`toast--${o}`);const d=(e/1e3).toFixed(2);n.style.animation=`slideInLeft ease 0.3s, fadeOut linear 1s ${d}s forwards`;n.innerHTML=`\n                    <div class="toast__icon">\n                        <i class="${c}"></i>\n\n                    </div>\n                    <div class="toast__body">\n                        <h3 class="toast__title">${s}</h3>\n                        <p class="toast__msg">${t} </p>\n                    </div>\n                    <div class="toast__close">\n                        <i class="fa-solid fa-xmark"></i>\n                    </div>\n                `;a.appendChild(n)}}function showSuccessToast(s,t="#toast"){toast({title:"Successful",message:s,type:"success",duration:1200,container:t})}function showErrorToast(){toast({title:"Error",message:"errorrrrrrrr, code cuar banj bij loiox",type:"error",duration:4e3})}function toast2({title:s="",message:t="",type:o="info",duration:e=3e3}){const n=document.getElementById("toast-2");if(n){if(n.firstChild){n.removeChild(n.firstChild)}const s=document.createElement("div");const a=setTimeout((function(){n.removeChild(s)}),e+1e3);s.classList.add("toastt-2",`toast-2--${o}`);const i=(e/1e3).toFixed(2);s.style.animation=`fadeIn ease 0.3s, fadeOut linear 1s ${i}s forwards`;s.innerHTML=`\n                <p class="toast__msg"  style="color: white">${t} </p>\n                `;n.appendChild(s)}}function showSuccessToast2(s,t="sound"){if(t=="sound"){playSound("assets/sound/successful.mp3")}toast2({title:"Successful",message:s,type:"success",duration:700})}function playSound(s){const t=new Audio(s);t.play()}function showErrorToast2(s,t="sound"){if(t=="sound"){playSound("assets/sound/error.mp3")}toast2({title:"error",message:s,type:"error",duration:700})}function showInfoToast2(s,t="sound"){if(t=="sound"){playSound("assets/sound/error.mp3")}toast2({title:"info",message:s,type:"info",duration:700})}